package app.noir.mobile;
import android.app.job.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import org.junit.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;
public final class BackgroundSyncTest {
 AuditPhoneFixture f;JobScheduler jobs;MainActivity activity;NoirSheet card;
 @Before public void setup()throws Exception{f=new AuditPhoneFixture();jobs=f.context.getSystemService(JobScheduler.class);jobs.cancel(BackgroundSync.JOB);BackgroundSync.device(f.data.context).edit().putBoolean("askedBattery",true).apply();}
 @After public void cleanup()throws Exception{if(card!=null)f.ui(card::dismiss);jobs.cancel(BackgroundSync.JOB);f.close();}
 void pair()throws Exception{f.data.rememberPeer("127.0.0.1:49272",new String(new char[64]).replace('\0','A'),new String(new char[64]).replace('\0','B'));assertTrue(f.data.paired());f.data.profiles.link(f.data.profileId,"default","Fixture","#E4C084","fixture-host");}
 JSONObject library()throws Exception{return new JSONObject().put("profileId","default").put("profileName","Fixture").put("profileColor","#E4C084").put("hostId","fixture-host").put("serverTime",System.currentTimeMillis()).put("favorites",new JSONArray()).put("items",new JSONArray());}
 @Test public void pairedOutboxIsDurableDeduplicatedAnyNetworkAndUnpairedQueuesNothing()throws Exception{f.data.queue(f.data.operation("unpaired","mark"));assertNull(jobs.getPendingJob(BackgroundSync.JOB));pair();f.data.queue(f.data.operation("paired","mark"));JobInfo job=jobs.getPendingJob(BackgroundSync.JOB);assertNotNull(job);assertEquals(JobInfo.NETWORK_TYPE_ANY,job.getNetworkType());assertEquals(2000,job.getMinLatencyMillis());assertEquals(30000,job.getInitialBackoffMillis());assertEquals(JobInfo.BACKOFF_POLICY_EXPONENTIAL,job.getBackoffPolicy());assertTrue(job.isPersisted());assertFalse(job.isPeriodic());assertEquals(f.data.profileId,job.getExtras().getString("profile"));f.data.renameLinkedProfile("Changed","#E4C084");assertEquals(1,jobs.getAllPendingJobs().stream().filter(j->j.getId()==BackgroundSync.JOB).count());NoirApp.scheduleSync(f.context);assertEquals(JobInfo.NETWORK_TYPE_ANY,jobs.getPendingJob(701).getNetworkType());}
 @Test public void periodicRevisionSkipsFullSyncUntilChangedAndOldPcFallsBack()throws Exception{pair();AtomicInteger full=new AtomicInteger();String[] revision={"r1"};f.data.fetchOverride=(path,body)->{if(path.equals("/v1/changes"))return new JSONObject().put("revision",revision[0]).put("profile","default");assertEquals("/v1/sync",path);full.incrementAndGet();return new JSONObject().put("revision",revision[0]).put("acknowledged",new JSONArray()).put("library",library());};assertTrue(BackgroundSync.run(f.data,true));assertEquals(1,full.get());assertFalse(BackgroundSync.run(f.data,true));assertEquals(1,full.get());assertTrue(f.data.lastSyncBackground());assertTrue(BackgroundSync.status(f.data).contains("in background"));revision[0]="r2";assertTrue(BackgroundSync.run(f.data,true));assertEquals(2,full.get());DataStore.PcFetch success=f.data.fetchOverride;f.data.fetchOverride=(path,body)->{if(path.equals("/v1/changes"))throw new DataStore.HttpStatus(404,"Old PC");return success.request(path,body);};assertTrue(BackgroundSync.run(f.data,true));assertEquals(3,full.get());assertNull(BackgroundSync.background.get());assertNull(jobs.getPendingJob(BackgroundSync.JOB));}
 /* S6: a library over the phone's 8 MiB cap: a plain message (English and Arabic), and nothing on the phone changes. */
 @Test public void tooLargeLibraryLeavesThePhoneAsItWas()throws Exception{pair();
  JSONObject good=library();good.getJSONArray("items").put(new JSONObject().put("id","kept-1").put("title","Kept Movie").put("movie",true).put("group","movie:kept-1"));
  f.data.fetchOverride=(path,body)->new JSONObject().put("revision","r1").put("acknowledged",new JSONArray()).put("library",good);f.data.sync();
  f.data.queue(f.data.operation("kept-1","mark"));String items=f.data.items().toString(),library=f.data.stateObject("library").toString();int pending=f.data.pendingCount();
  f.data.fetchOverride=(path,body)->{JSONObject big=library();JSONArray many=big.getJSONArray("items");for(int n=0;n<40000;n++)many.put(new JSONObject().put("id","big-"+n).put("title","A title long enough to fill the response "+n).put("summary",new String(new char[200]).replace('\0','x')));return new JSONObject(new String(DataStore.read(new java.io.ByteArrayInputStream(new JSONObject().put("revision","r2").put("acknowledged",new JSONArray()).put("library",big).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)),DataStore.maxLibraryBytes),java.nio.charset.StandardCharsets.UTF_8));};
  try{f.data.sync();fail("an oversized library must not sync");}catch(java.io.IOException e){assertEquals(DataStore.LIBRARY_TOO_LARGE,e.getMessage());assertTrue(e.getCause() instanceof DataStore.TooLarge);}
  assertEquals(DataStore.LIBRARY_TOO_LARGE,f.data.connection);assertEquals("the phone's items are unchanged",items,f.data.items().toString());assertEquals("the saved library is unchanged",library,f.data.stateObject("library").toString());assertEquals("pending changes wait for the next sync",pending,f.data.pendingCount());
  assertTrue(Loc.AR.get(DataStore.LIBRARY_TOO_LARGE).matches("(?s).*[\\u0600-\\u06FF].*"));
  Loc.arabic=true;try{f.data.sync();fail();}catch(java.io.IOException e){assertEquals(Loc.AR.get(DataStore.LIBRARY_TOO_LARGE),e.getMessage());}finally{Loc.arabic=false;}
 }
 @Test public void pendingOpsBypassProbeAndReapplyDoesNotScheduleLoop()throws Exception{pair();JSONObject op=f.data.operation("unknown","mark");f.data.queue(op);jobs.cancel(BackgroundSync.JOB);f.data.fetchOverride=(path,body)->{assertEquals("/v1/sync",path);return new JSONObject().put("revision","r").put("acknowledged",new JSONArray()).put("library",library());};assertTrue(BackgroundSync.run(f.data,true));assertEquals(1,f.data.pendingCount());assertNull(jobs.getPendingJob(BackgroundSync.JOB));}
 @Test public void networkTriggersAreThrottledAndBatteryDeclineStaysQuietInArabic()throws Exception{activity=f.launch(MainActivity.class);pair();BackgroundSync.device(f.data.context).edit().putLong("networkTrigger",0).apply();BackgroundSync.network(f.context);assertNotNull(jobs.getPendingJob(BackgroundSync.JOB));jobs.cancel(BackgroundSync.JOB);BackgroundSync.network(f.context);assertNull(jobs.getPendingJob(BackgroundSync.JOB));f.ui(()->{Loc.arabic=true;BackgroundSync.device(f.data.context).edit().putBoolean("askedBattery",false).apply();card=BackgroundSync.batteryCard(activity);assertTrue(BackgroundSync.device(f.data.context).getBoolean("askedBattery",false));assertEquals(View.LAYOUT_DIRECTION_RTL,card.root.getLayoutDirection());assertNotEquals("Keep Noir in sync in the background",Loc.t("Keep Noir in sync in the background"));AuditPhoneFixture.click(card.root,"Not now");assertFalse(card.dialog.isShowing());BackgroundSync.maybeAsk(activity);assertFalse(card.dialog.isShowing());activity.page="Settings";activity.render();assertNotNull(AuditPhoneFixture.find(activity.body,v->Loc.t("Background sync").equals(v.getContentDescription())));assertTrue(AuditPhoneFixture.all(activity.body,v->v instanceof TextView&&((TextView)v).getText().toString().contains(Loc.t(BackgroundSync.allowed(activity)?"On":"May be delayed by Android · Allow"))).size()>0);});}
}
